def _domain_of(identity):
    if identity.startswith("sip:"):
        at = identity.find("@")
        if at > 4:
            return identity[at + 1:]
    return None


def process_batch(obj):
    if not isinstance(obj, dict):
        return {"results": []}
    directory = obj.get("directory")
    accounts = obj.get("accounts")
    gateways = obj.get("gateways")
    jobs = obj.get("jobs")
    if not isinstance(directory, dict):
        directory = {}
    if not isinstance(accounts, dict):
        accounts = {}
    if not isinstance(gateways, dict):
        gateways = {}
    if not isinstance(jobs, list):
        jobs = []

        jobs = []

    alias = {}
    for identity, aliases in directory.items():
        if isinstance(identity, str):
            alias[identity] = identity
            if isinstance(aliases, list):
                for item in aliases:
                    if isinstance(item, str):
                        alias[item] = identity
    alias.pop(ANON, None)

    domain_cache = {}

    def domain_of(identity):
        dom = domain_cache.get(identity, 0)
        if dom == 0:
            dom = _domain_of(identity)
            domain_cache[identity] = dom
        return dom

    gateway_cache = {}

    def gateway_of(name):
        info = gateway_cache.get(name)
        if info is None:
            local = frozenset()
            peers = {}
            entry = gateways.get(name)
            if isinstance(entry, dict):
                doms = entry.get("local_domains")
                if isinstance(doms, list):
                    local = frozenset(x for x in doms if isinstance(x, str))
                peer_map = entry.get("peers")
                if isinstance(peer_map, dict):
                    for peer, listed in peer_map.items():
                        if isinstance(listed, list):
                            peers[peer] = frozenset(
                                x for x in listed if isinstance(x, str))
                        else:
                            peers[peer] = frozenset()
            info = (local, peers)
            gateway_cache[name] = info
        return info

    def account_of(subject):
        entry = accounts.get(subject)
        if not isinstance(entry, dict):
            return None
        primary = entry.get("primary")
        if not isinstance(primary, str):
            primary = None
        allowed = set()
        if primary is not None:
            allowed.add(primary)
        listing = entry.get("allow")
        if isinstance(listing, list):
            for item in listing:
                if isinstance(item, str):
                    allowed.add(item)
        return primary, frozenset(allowed)

    results = []
    wires = []
    for job in jobs:
        try:
            result, wire = decide(job, wires, alias, domain_of, gateway_of,
                                  account_of, accounts)
        except Reject as exc:
            result, wire = {"status": "reject", "reason": exc.reason}, None
        except Exception:
            # Unreachable for well formed context; keep the batch alive anyway.
            result, wire = {"status": "reject", "reason": "syntax"}, None
        results.append(result)
        wires.append(wire)
    return {"results": results}


def decide(job, wires, alias, domain_of, gateway_of, account_of, accounts):
    reject = lambda reason: ({"status": "reject", "reason": reason}, None)

    if not isinstance(job, dict):
