            elif selected != found:
                return reject("identity")
        if not parsed.fanon and alias.get(parsed.furi) != selected:
            return reject("identity")
        if parsed.ppi is not None and alias.get(parsed.ppi) != selected:
            return reject("identity")
        if parsed.rpid is not None and alias.get(parsed.rpid) != selected:
            return reject("identity")
        basis = "peer"
    else:
        return reject("unauthenticated")

    private = parsed.fanon or parsed.privacy == "id"
    trusted_out = job.get("trusted_out", False)
    emit_pai = (not private) or bool(trusted_out)

    from_uri = ANON if private else selected
    lines = [
        parsed.method + " " + parsed.ruri + " SIP/2.0",
        "From: <" + from_uri + (">;tag=" + parsed.ftag if parsed.ftag else ">"),
        "To: <" + parsed.turi + (">;tag=" + parsed.ttag if parsed.ttag else ">"),
        "Call-ID: " + parsed.callid,
        "CSeq: " + str(parsed.cseq) + " " + parsed.method,
        "Privacy: " + ("id" if private else "none"),
    ]
    if emit_pai:
        lines.append("P-Asserted-Identity: <" + selected + ">")
    if parsed.ctype is not None:
        lines.append("Content-Type: " + parsed.ctype)
    lines.append("Content-Length: " + str(len(parsed.body)))
    wire = "\r\n".join(lines) + "\r\n\r\n" + parsed.body

    return ({"status": "accept", "identity": selected, "basis": basis,
             "private": private, "wire": wire}, wire)


